// Batch 2: prog name derivation, -- handling, option-like values, repeats.
import { raw, EXE } from './drv.mjs';
import { execFileSync } from 'node:child_process';
import fs from 'node:fs';

// --- prog name derivation: invoke via symlink with a different basename ---
const linkDir = '/tmp/pl';
fs.mkdirSync(linkDir, { recursive: true });
for (const nm of ['zz_other', 'weird name.exe', 'a.b.c']) {
  const p = `${linkDir}/${nm}`;
  try { fs.unlinkSync(p); } catch {}
  fs.symlinkSync(EXE, p);
}
function rawAt(exe, argv, opts = {}) {
  try {
    const out = execFileSync(exe, argv, { encoding: 'utf8', stdio: ['ignore', 'pipe', 'pipe'], ...opts });
    return { out, err: '', code: 0 };
  } catch (e) {
    return { out: e.stdout ?? '', err: e.stderr ?? String(e.message), code: e.status ?? -1 };
  }
}
const progTests = [];
for (const nm of ['zz_other', 'weird name.exe', 'a.b.c']) {
  progTests.push({ how: `symlink ${nm}`, ...rawAt(`${linkDir}/${nm}`, []) });
}
// relative path invocation
progTests.push({ how: 'relative ./zz_other', ...rawAt('./zz_other', [], { cwd: linkDir }) });
progTests.push({ how: 'via sh -c with argv0 override', ...rawAt('/bin/sh', ['-c', 'exec -a FAKEARGV0 "$0"', EXE]) });

const cases = [
  // -- separator variants
  ['--a', 'X', '--b', 'Y', '--', '--'],
  ['--a', 'X', '--b', 'Y', '--', 'Z'],
  ['--', '--a=X', '--b=Y'],
  ['--a=X', '--b=Y', '--'],
  ['--a=X', '--', '--b=Y'],
  ['--'],
  ['--', '--'],
  ['-'],
  ['--a', '-'],
  ['--a', '-', '--b', '-'],
  // option-like values
  ['--a', '-x', '--b', 'Y'],
  ['--a=-x', '--b=Y'],
  ['--a', '-1', '--b', 'Y'],
  ['--a', '-1.5', '--b', '2'],
  ['--a', '-1x', '--b', 'Y'],
  ['--a=--', '--b=Y'],
  ['--a', '--', '--b', 'Y'],   // dup of earlier but keep
  ['--a', '', '--b', 'Y'],
  ['--a=', '--b=Y'],
  ['--a', ' X ', '--b', 'Y'],
  ['--a', '=X', '--b', 'Y'],
  ['--a==X', '--b=Y'],
  ['--a', 'a b', '--b', 'a  b'],
  ['--a', '--help', '--b', 'Y'],
  ['--a', '-h', '--b', 'Y'],
  ['--a', '--c', '--b', 'Y'],
  ['--a', '+1', '--b', 'Y'],
  ['--a', '-', '--b', 'Y'],
  // repeated
  ['--a', 'X', '--a', 'Y', '--b', 'Z'],
  ['--a', 'X', '--b', 'Y', '--b', 'Z'],
  ['--a=X', '--a=Y', '--b=Z'],
  // interspersed / greedy
  ['--a', 'X', 'Y', '--b', 'Z'],
  ['--a', 'X', 'Y', 'Z'],
  // abbreviation-ish
  ['--A', 'X', '--b', 'Y'],
  ['--ab', 'X'],
  ['--a', 'X', '--b', 'Y', '-x'],
  ['--a', 'X', '--b', 'Y', '-1'],
  ['--a', 'X', '--b', 'Y', '--a=Q'],
];

const out = { progTests, cases: [] };
for (const argv of cases) out.cases.push({ argv, ...raw(argv) });
console.log(JSON.stringify(out, null, 1));

