  try {
    const out = execFileSync(EXE, argv, { encoding: 'utf8', stdio: ['ignore', 'pipe', 'pipe'], env: { ...process.env, ...env } });
    return { out, err: '', code: 0 };
  } catch (e) { return { out: e.stdout ?? '', err: e.stderr ?? String(e.message), code: e.status ?? -1 }; }
}

