// Candidate pure-Node reimplementation of the argparse CLI layer.
// Exported so cli_diff.mjs can differentially test it against the executable.

export const PROG = 'test1_executable';
export const USAGE = `usage: ${PROG} [-h] --a A --b B`;
export const HELP =
  USAGE + '\n' +
  '\n' +
  'options:\n' +
  '  -h, --help  show this help message and exit\n' +
  '  --a A\n' +
  '  --b B\n';

const NEG_NUM = /^-\d+$|^-\d*\.\d+$/;

// insertion order matters for ambiguity messages
const HELP_ACTION = { nargs: 0, optionStrings: ['-h', '--help'], dest: 'help', required: false };
const A_ACTION = { nargs: null, optionStrings: ['--a'], dest: 'a', required: true };
const B_ACTION = { nargs: null, optionStrings: ['--b'], dest: 'b', required: true };
const ACTIONS = [HELP_ACTION, A_ACTION, B_ACTION];          // definition order
const OPTS = new Map([                                       // _option_string_actions order
  ['-h', HELP_ACTION], ['--help', HELP_ACTION],
  ['--a', A_ACTION], ['--b', B_ACTION],
]);

class Exit { constructor(code, out, err) { this.code = code; this.out = out; this.err = err; } }

export function parse(argv) {
  const outBuf = [];
  const fail = (msg) => { throw new Exit(2, outBuf.join(''), USAGE + '\n' + PROG + ': error: ' + msg + '\n'); };
  const failArg = (action, msg) => fail('argument ' + action.optionStrings.join('/') + ': ' + msg);

  function getOptionTuples(s) {
    const res = [];
    if (s[0] === '-' && s[1] === '-') {
      let prefix = s, ea = null;
      const eq = s.indexOf('=');
      if (eq >= 0) { prefix = s.slice(0, eq); ea = s.slice(eq + 1); }
      for (const [os, act] of OPTS) if (os.startsWith(prefix)) res.push([act, os, ea]);
    } else if (s[0] === '-' && s[1] !== '-') {
      const prefix = s, shortPrefix = s.slice(0, 2), shortEA = s.slice(2);
      for (const [os, act] of OPTS) {
        if (os === shortPrefix) res.push([act, os, shortEA]);
        else if (os.startsWith(prefix)) res.push([act, os, null]);
      }
    }
    return res;
  }

  function parseOptional(s) {
    if (s === '') return null;
    if (s[0] !== '-') return null;
    if (OPTS.has(s)) return [OPTS.get(s), s, null];
    if (s.length === 1) return null;
    const eq = s.indexOf('=');
    if (eq >= 0) {
      const os = s.slice(0, eq);
      if (OPTS.has(os)) return [OPTS.get(os), os, s.slice(eq + 1)];
    }
    const tuples = getOptionTuples(s);
    if (tuples.length > 1) fail(`ambiguous option: ${s} could match ${tuples.map(t => t[1]).join(', ')}`);
    if (tuples.length === 1) return tuples[0];
    if (NEG_NUM.test(s)) return null;       // no negative-number-looking options exist
    if (s.includes(' ')) return null;
    return [null, s, null];
  }

  // ---- build pattern ----
  const pattern = [];            // 'O' | 'A' | '-'
  const optTuples = new Map();
  let sawSep = false;
  for (let i = 0; i < argv.length; i++) {
    if (!sawSep && argv[i] === '--') { pattern.push('-'); sawSep = true; continue; }
    if (sawSep) { pattern.push('A'); continue; }
    const t = parseOptional(argv[i]);
    if (t === null) pattern.push('A');
    else { optTuples.set(i, t); pattern.push('O'); }
  }

  const extras = [];
  const seen = new Set();
  const ns = { a: null, b: null };

  const takeAction = (action, args, optString) => {
    seen.add(action);
    if (action === HELP_ACTION) throw new Exit(0, outBuf.join('') + HELP, '');
    ns[action.dest] = args[0];
  };

  // nargs matching for an OPTIONAL action: '-' is not allowed in the pattern
  const matchArgument = (action, patStr) => {
    if (action.nargs === 0) return 0;
    if (patStr[0] === 'A') return 1;
    failArg(action, 'expected one argument');
  };

  function consumeOptional(startIndex) {
    let [action, optString, explicitArg] = optTuples.get(startIndex);
    const argString = argv[startIndex];
    const actionTuples = [];
    let stop;
    for (;;) {
      if (action === null) { extras.push(argString); return startIndex + 1; }
      if (explicitArg !== null && explicitArg !== undefined) {
        const argCount = matchArgument(action, 'A');
        if (argCount === 0 && optString[1] !== '-' && explicitArg !== '') {
          actionTuples.push([action, [], optString]);
          const char = optString[0];
          optString = char + explicitArg[0];
          const newEA = explicitArg.slice(1) || null;
          if (OPTS.has(optString)) { action = OPTS.get(optString); explicitArg = newEA; continue; }
          extras.push(char + explicitArg);
          stop = startIndex + 1;
          break;
        } else if (argCount === 1) {
          stop = startIndex + 1;
          actionTuples.push([action, [explicitArg], optString]);
          break;
        } else {
          failArg(action, `ignored explicit argument '${explicitArg}'`);
        }
      } else {
        const start = startIndex + 1;
        const argCount = matchArgument(action, pattern.slice(start).join(''));
        stop = start + argCount;
        actionTuples.push([action, argv.slice(start, stop), optString]);
        break;
      }
    }
    for (const [act, args, os] of actionTuples) takeAction(act, args, os);
    return stop;
  }

  // ---- main loop (no positionals defined => every non-option token is an extra) ----
  const optIdx = [...optTuples.keys()].sort((x, y) => x - y);
  const maxOpt = optIdx.length ? optIdx[optIdx.length - 1] : -1;
  let i = 0;
  while (i <= maxOpt) {
    const next = optIdx.find((k) => k >= i);
    if (i !== next) { for (let j = i; j < next; j++) extras.push(argv[j]); i = next; }
    i = consumeOptional(i);
  }
  for (let j = i; j < argv.length; j++) extras.push(argv[j]);

  // ---- required check (definition order) ----
  const missing = ACTIONS.filter((a) => a.required && !seen.has(a)).map((a) => a.optionStrings.join('/'));
  if (missing.length) fail('the following arguments are required: ' + missing.join(', '));

  if (extras.length) fail('unrecognized arguments: ' + extras.join(' '));

  return { a: ns.a, b: ns.b };
}

// Full program behaviour for simple ASCII values (repr = single-quoted, no escapes needed).
export function simulate(argv) {
  try {
    const { a, b } = parse(argv);
    const body = a === b
      ? '{}'
      : `{'values_changed': {'root': {'new_value': '${b}', 'old_value': '${a}'}}}`;
    return { out: body + '\n', err: '', code: 0 };
  } catch (e) {
    if (e instanceof Object && 'code' in e) return { out: e.out, err: e.err, code: e.code };
    throw e;
  }
}
